// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));
        bool ok;
        vm.prank(attacker);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertFalse(ok);
    }
}
